class Checker:
    def _from_level(self, values):
        if not values:
            return None
        nodes = [None if v is None else TreeNode(v) for v in values]
        kids = nodes[::-1]
        root = kids.pop()
        for node in nodes:
            if node is not None:
                if kids:
                    node.left = kids.pop()
                if kids:
                    node.right = kids.pop()
        return root

    def _normalize(self, node):
        if node is None:
            return None
        if hasattr(node, "val"):
            return node
        if isinstance(node, list):
            return self._from_level(node)
        if isinstance(node, dict):
            return TreeNode(
                node.get("val", node.get("value")),
                self._normalize(node.get("left")),
                self._normalize(node.get("right")),
            )
        return None

    def bstToGst(self, root, result):
        def inorder_vals(node, vals):
            if node is None:
                return
            inorder_vals(node.left, vals)
            vals.append(node.val)
            inorder_vals(node.right, vals)

        def reverse_inorder_assign(node, acc):
            if node is None:
                return
            reverse_inorder_assign(node.right, acc)
            acc[0] += node.val
            node.val = acc[0]
            reverse_inorder_assign(node.left, acc)

        expected_root = self._normalize(root)
        actual_root = self._normalize(result)
        reverse_inorder_assign(expected_root, [0])

        expected = []
        inorder_vals(expected_root, expected)
        actual = []
        inorder_vals(actual_root, actual)
        return expected == actual

